import {validateAdditionalFields} from './personnel-options.js';
export const schools=['วิทยาลัยเทคนิคระนอง','วิทยาลัยเทคนิคพังงา','วิทยาลัยเทคนิคภูเก็ต','วิทยาลัยอาชีวศึกษาภูเก็ต','วิทยาลัยเทคนิคกระบี่','วิทยาลัยเทคนิคตรัง','วิทยาลัยการอาชีพตรัง','สถาบันการอาชีวศึกษาภาคใต้ 2'];
export const provinces=['ระนอง','พังงา','ภูเก็ต','ภูเก็ต','กระบี่','ตรัง','ตรัง','ภูเก็ต'];
export const types=['ก.ค.ศ.16 (ทะเบียนประวัติ)','วุฒิการศึกษา / ใบรับรอง / ปริญญา','คำสั่งแต่งตั้ง / บรรจุ / ย้าย / โอน','เปลี่ยนตำแหน่ง / วิทยฐานะ','ใบประกอบวิชาชีพ','วุฒิบัตรอบรม / เกียรติบัตร','คำสั่งเลื่อนเงินเดือน / เอกสารเงินเดือน','เอกสารส่วนตัว','เครื่องราชอิสริยาภรณ์'];
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
// getRandomValues also works on local HTTP previews where randomUUID is unavailable.
export function uuid(){if(globalThis.crypto.randomUUID)return globalThis.crypto.randomUUID();const bytes=globalThis.crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;}
export function elapsed(date,asof=today()){if(!date||date>asof)return null;const a=new Date(date+'T00:00:00Z'),b=new Date(asof+'T00:00:00Z');if(isNaN(a)||isNaN(b))return null;let m=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth();if(b.getUTCDate()<a.getUTCDate())m--;return {years:Math.floor(m/12),months:m%12};}
export function retirement(birth,override=''){if(override)return override;if(!birth)return '';const [y,m,d]=birth.split('-').map(Number);if(!y||!m||!d)return '';return `${y+60+((m>10||(m===10&&d>1))?1:0)}-09-30`;}
export function safeCell(v){const s=String(v??'');return /^[=+\-@\t\r]/.test(s)?"'"+s:s;}
export function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>'"'+safeCell(v).replaceAll('"','""')+'"').join(',')).join('\r\n');}
export function parseCSV(text){let rows=[],row=[],v='',q=false;const s=text.replace(/^\uFEFF/,'');for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++;}else q=!q;}else if(c===','&&!q){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(v);if(row.some(x=>x!==''))rows.push(row);row=[];v='';}else v+=c;}if(q)throw Error('เครื่องหมายคำพูด CSV ไม่ครบ');row.push(v);if(row.some(x=>x!==''))rows.push(row);return rows;}
export function completeness(person,docs,docTypes){const required=docTypes.filter(t=>t.required&&(!t.positions?.length||t.positions.includes(person.position)));const approved=new Set(docs.filter(d=>d.personnel_id===person.id&&d.status==='approved').map(d=>d.type_id));return {total:required.length,done:required.filter(t=>approved.has(t.id)).length,percent:required.length?Math.round(required.filter(t=>approved.has(t.id)).length/required.length*100):100};}
export function parseEducationMajors(value){return (Array.isArray(value)?value:String(value??'').split(/[;\r\n]+/)).map(v=>String(v).trim()).filter(Boolean);}
export function validatePerson(p){validateAdditionalFields(p);if(Object.hasOwn(p,'address'))throw Error('รุ่น 1.9 ไม่จัดเก็บข้อมูลที่อยู่');if(String(p.work_unit||'').length>300)throw Error('งาน/แผนก/กลุ่มงานยาวเกินกำหนด');if(!p.employee_code?.trim()||!p.full_name?.trim())throw Error('กรุณาระบุเลขที่ตำแหน่งและชื่อ');if(p.highest_education&&p.highest_education.length>200)throw Error('วุฒิการศึกษายาวเกินกำหนด');if(p.education_majors!==undefined){const a=p.education_majors;if(!Array.isArray(a)||a.length>20||a.some(v=>typeof v!=='string'||!v.trim()||v.length>200))throw Error('ระบุสาขาวิชาได้ไม่เกิน 20 สาขา สาขาละไม่เกิน 200 ตัวอักษร');if(new Set(a.map(v=>v.trim())).size!==a.length)throw Error('มีสาขาวิชาซ้ำ');if(a.length&&!p.highest_education?.trim())throw Error('กรุณาระบุวุฒิการศึกษาสูงสุดของสาขาวิชา');}if(!Number.isInteger(+p.school_id)||+p.school_id<1||+p.school_id>2147483647)throw Error('สถานศึกษาไม่ถูกต้อง');for(const k of ['birth_date','start_date'])if(p[k]&&(!/^\d{4}-\d{2}-\d{2}$/.test(p[k])||isNaN(Date.parse(p[k]))||new Date(p[k]).toISOString().slice(0,10)!==p[k]||p[k]>today()))throw Error('วันที่ไม่ถูกต้องหรือเป็นวันในอนาคต');if(p.birth_date&&p.start_date&&p.start_date<p.birth_date)throw Error('วันบรรจุต้องหลังวันเกิด');return p;}
